ALTER TABLE public.monthly_clients ADD COLUMN IF NOT EXISTS retired_at timestamptz;
CREATE OR REPLACE FUNCTION public.monthly_cleanup_user_allowed(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT coalesce(p_user=ANY(ARRAY['2745fb7f-8604-4d02-8645-437e4cd635c1'::uuid,'716ae187-2086-4b5d-9a87-064fe42dbcdb'::uuid,'76a43a8c-0fc9-4a59-9bfc-7b7b7efb89d5'::uuid,'8a44551b-923c-436c-b0a7-212b8fa2c2f3'::uuid,'c753e482-67d3-4bc9-ab13-0e1294da1f8a'::uuid,'e450b9cb-50c6-477d-adce-53a6d7b04a3d'::uuid]) AND EXISTS(SELECT 1 FROM auth.users WHERE id=p_user AND email ~ '^bluepipe-monthly-[0-9a-f]{32}-[a-z0-9-]+@example\.invalid$'),false) $$;
REVOKE ALL ON FUNCTION public.monthly_cleanup_user_allowed(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.monthly_cleanup_auth_begin(p_user uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE a uuid:=monthly_require_real_admin(); receipt uuid; BEGIN IF monthly_cleanup_user_allowed(p_user) IS NOT TRUE OR p_user=a THEN RAISE EXCEPTION 'Reserved fixture required' USING ERRCODE='42501'; END IF; INSERT INTO monthly_audit_log(actor,action,target_table,target_id,detail) VALUES(a,'synthetic_auth_disable_intent','monthly_staff',p_user,jsonb_build_object('ban_hours',876000)) RETURNING id INTO receipt; RETURN receipt; END $$;
CREATE OR REPLACE FUNCTION public.monthly_cleanup_auth_finish(p_intent uuid,p_disabled boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE a uuid:=monthly_require_real_admin(); target uuid; receipt uuid; BEGIN SELECT target_id INTO target FROM monthly_audit_log WHERE id=p_intent AND actor=a AND action='synthetic_auth_disable_intent'; IF target IS NULL OR monthly_cleanup_user_allowed(target) IS NOT TRUE THEN RAISE EXCEPTION 'Invalid intent'; END IF; IF p_disabled IS TRUE AND NOT EXISTS(SELECT 1 FROM auth.users WHERE id=target AND banned_until>now()) THEN RAISE EXCEPTION 'Readback mismatch'; END IF; INSERT INTO monthly_audit_log(actor,action,target_table,target_id,detail) VALUES(a,'synthetic_auth_disable_outcome','monthly_staff',target,jsonb_build_object('intent_id',p_intent,'disabled',coalesce(p_disabled,false))) RETURNING id INTO receipt; RETURN receipt; END $$;
CREATE OR REPLACE FUNCTION public.monthly_cleanup_retire_clients(p_clients uuid[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a uuid:=monthly_require_real_admin(); receipt uuid; allowed uuid[]:=ARRAY['05bdc916-34bf-4c95-bc7e-da67705ea9ba'::uuid,'072a70f4-21e1-484f-bec0-1d29315f1926'::uuid,'096c7162-a98c-4ea3-8378-a1c9dc0f8a56'::uuid,'0a2b2a8d-cf1c-40e4-ba07-a0bc2805758c'::uuid,'0edcb17c-b8c2-4f19-9379-14ae648c9772'::uuid,'1277da41-fb23-4335-9bb7-0afbc5208f9c'::uuid,'193ab354-9955-48b2-b2d3-8eafea43d2fc'::uuid,'19868fc0-7c15-42bc-82af-7eacc666009c'::uuid,'1a1dccf2-9c76-47fd-92fc-6306323823d3'::uuid,'1cd442ff-e8b7-4c9a-941e-6be14ce2f44b'::uuid,'1da7fc7c-a7c0-4e4e-a9ec-7199b5fba3b1'::uuid,'1f6994f5-3c76-4fce-9129-b4be7e03a44e'::uuid,'233204fe-307a-49f2-b456-4038681d840d'::uuid,'2935120c-2b0f-4bb9-8792-1b5eeeb8b5fa'::uuid,'2ff9842a-f4de-4fac-bf48-01c6a7611b8f'::uuid,'35892360-e8ce-48b0-bac5-2a8f0ba1a3f0'::uuid,'3666a267-20bd-4314-99d0-00675d85f03e'::uuid,'3e0f8c00-5a93-496d-99ed-794454e52fb4'::uuid,'3f4265ae-aa37-40c1-a396-1195dfdab5cd'::uuid,'44ffe850-c0f2-4b1f-97e6-ed39f31c4915'::uuid,'462460ae-21f1-4132-80be-c8894db4030c'::uuid,'464b79b5-d4d1-437f-94d3-e0fa0e7809f7'::uuid,'524e8576-2bf5-4615-b428-e04c48a8f3af'::uuid,'532b49be-5484-450a-971f-cc610798b27f'::uuid,'595f721f-a0a8-4f05-b4df-49bf9a7979c8'::uuid,'6139d786-7e75-4147-8b6d-0fcfad17892d'::uuid,'6367d271-30e5-4fc7-a04d-71a4be88c5cc'::uuid,'65c0654b-74fa-4293-b007-af6b2d88b25f'::uuid,'6617128f-8f64-4331-a345-237753d25acd'::uuid,'67930628-8355-40bf-b505-c25ce1b2c09f'::uuid,'6898c065-4a57-4cc6-b092-b9222db1af45'::uuid,'6b6e7040-6ec7-4aa6-a8f9-1e310811a4cc'::uuid,'7196d841-f8b6-4bba-80d8-b57b3e91219a'::uuid,'74e90806-e98f-41e6-8154-a593e4bb830d'::uuid,'7524f259-5b09-4488-84b7-d6d86c438130'::uuid,'75e284d6-12a8-45e6-aec0-7ddbefff5fb0'::uuid,'7a2578f0-feb3-4540-856c-035fd1adc1a6'::uuid,'7e2c5c99-3822-472c-ad51-1a74f071882e'::uuid,'84e1eeb0-96b9-4860-b500-0d103ef527f3'::uuid,'856c2595-34b5-4739-9b26-13a8ba19f947'::uuid,'86dc744b-edec-4fab-a9f7-311b400c86e9'::uuid,'89b724e8-7706-4708-8c56-64df51390397'::uuid,'8f66353a-6f1f-4899-84f5-229d3df24562'::uuid,'93fcbca9-545d-4161-aa52-4a9673ee1a5b'::uuid,'94245455-9fef-48dc-bd5e-be2226c3a029'::uuid,'94bba07f-c1d4-4a48-8a87-8e393abefa4d'::uuid,'951536c8-89a1-41b8-9401-fb853cdae66c'::uuid,'98e3d06e-b571-492a-a077-15a26c523b0c'::uuid,'99436dda-5220-4af8-99ea-283a91082114'::uuid,'ad4a08d1-83f3-4a39-941a-592e4d8cd2e1'::uuid,'ae14c7a4-0d8a-43bd-af88-9d98d31aacd0'::uuid,'b3b144cc-9ce1-4bad-83c4-10388b05f5f9'::uuid,'b8410b6f-583e-4f80-956e-c08c06fa01ee'::uuid,'b8f1c8df-937f-46a9-8fbc-6e8e9c9490d7'::uuid,'b958b7d6-3ef8-485a-8c70-141837da46ed'::uuid,'bf573164-9426-45ee-8054-41394e1b9fc6'::uuid,'ca53c1c3-72e7-4a6f-b6ef-75a3d9279a07'::uuid,'cb5978fb-91dd-4cc2-bfc0-19aa1cbb440a'::uuid,'cfa7d63c-1408-4530-aecd-20ee43a8fd5a'::uuid,'d02423a8-fc01-449e-a7b6-4b938042534f'::uuid,'d0bdc4bc-5b77-47f3-8165-2b9e36179962'::uuid,'d50cb390-83a6-42e5-8872-ab3388f23d6a'::uuid,'d7086177-3bd6-4935-9348-0bf510cddaa4'::uuid,'da30d0e7-2890-4791-9a83-8c0f8430a7cb'::uuid,'dab3896a-e8b7-4225-b118-340fc888acf1'::uuid,'dcb08834-6312-4166-849e-0582fd63bb03'::uuid,'e8d4624e-2b23-4d25-9812-7702e543be5f'::uuid,'ea255f4e-c405-4581-b341-30b967ccd837'::uuid,'ed11db95-cf64-46e3-be62-e7810982bfee'::uuid,'ee1b21bd-2008-4612-a10a-26c8750fece8'::uuid,'ee7af095-4d68-47fe-b5c2-841160e32ff4'::uuid,'efef157d-65d6-4d93-aad2-f95fb3223d1a'::uuid,'fd580709-51c4-476a-a001-c67109f347b9'::uuid,'ff818825-c728-499e-aa0f-63e7011e516b'::uuid];
BEGIN IF p_clients IS NULL OR cardinality(p_clients)<>74 OR (SELECT count(DISTINCT x) FROM unnest(p_clients)x)<>74 OR NOT(p_clients @> allowed AND allowed @> p_clients) OR (SELECT count(*) FROM monthly_clients WHERE id=ANY(p_clients) AND slug ~ '^(test-|syn-)')<>74 THEN RAISE EXCEPTION 'Exact fixture allowlist required' USING ERRCODE='42501'; END IF;
INSERT INTO monthly_audit_log(actor,action,target_table,detail) VALUES(a,'synthetic_clients_retired','monthly_clients',jsonb_build_object('client_ids',to_jsonb(p_clients),'count',74,'files_deleted',false)) RETURNING id INTO receipt;
UPDATE monthly_clients SET status='retired',retired_at=coalesce(retired_at,now()) WHERE id=ANY(p_clients); RETURN receipt; END $$;
CREATE OR REPLACE FUNCTION public.monthly_can_client(cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT monthly_staff_role() IN ('admin','approver','editor') AND EXISTS(SELECT 1 FROM monthly_clients WHERE id=cid AND retired_at IS NULL) $$;
CREATE OR REPLACE FUNCTION public.monthly_can_version(vid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT monthly_staff_role() IN ('admin','approver','editor') AND EXISTS(SELECT 1 FROM monthly_report_versions v JOIN monthly_reports r ON r.id=v.report_id JOIN monthly_clients c ON c.id=r.client_id WHERE v.id=vid AND c.retired_at IS NULL) $$;
ALTER POLICY monthly_client_select ON public.monthly_clients USING(monthly_can_client(id));
ALTER POLICY monthly_report_select ON public.monthly_reports USING(monthly_can_client(client_id));
CREATE OR REPLACE FUNCTION public.monthly_retired_write_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE cid uuid; BEGIN IF TG_TABLE_NAME='monthly_report_versions' THEN SELECT client_id INTO cid FROM monthly_reports WHERE id=NEW.report_id; ELSE cid:=NEW.client_id; END IF; IF EXISTS(SELECT 1 FROM monthly_clients WHERE id=cid AND retired_at IS NOT NULL) THEN RAISE EXCEPTION 'Retired fixture' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER monthly_retired_report_guard BEFORE INSERT OR UPDATE ON monthly_reports FOR EACH ROW EXECUTE FUNCTION monthly_retired_write_guard();
CREATE TRIGGER monthly_retired_version_guard BEFORE INSERT OR UPDATE ON monthly_report_versions FOR EACH ROW EXECUTE FUNCTION monthly_retired_write_guard();
CREATE TRIGGER monthly_retired_stage_guard BEFORE INSERT OR UPDATE ON monthly_staging FOR EACH ROW EXECUTE FUNCTION monthly_retired_write_guard();
CREATE TRIGGER monthly_retired_scope_guard BEFORE INSERT OR UPDATE ON monthly_code_scopes FOR EACH ROW EXECUTE FUNCTION monthly_retired_write_guard();
REVOKE ALL ON FUNCTION public.monthly_cleanup_auth_begin(uuid),public.monthly_cleanup_auth_finish(uuid,boolean),public.monthly_cleanup_retire_clients(uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.monthly_cleanup_auth_begin(uuid),public.monthly_cleanup_auth_finish(uuid,boolean),public.monthly_cleanup_retire_clients(uuid[]) TO authenticated;
-- Non-destructive rollback retains retirement column, audit and denied fixture access.